INSERT INTO challenge_tests (test_set, idx, input, gen, expected, sample) VALUES ('histogram', 9, NULL, 'def gen():
    _s = [1347310900]
    def _n():
        _s[0] = (_s[0] * 1103515245 + 12345) % 2147483648
        return _s[0] >> 8
    def r(lo, hi):
        return lo + ((_n() << 23) | _n()) % (hi - lo + 1)
    V = 1000000000
    MODE = 0
    N = 200000
    if MODE == 1:
        a = list(range(1, N + 1))
    elif MODE == 2:
        a = [V] * N
    else:
        a = [r(0, V) for _ in range(N)]
    return f"{N}\n{'' ''.join(map(str, a))}\n"
', '15729632544', 0);
INSERT INTO challenge_tests (test_set, idx, input, gen, expected, sample) VALUES ('histogram', 10, NULL, 'def gen():
    _s = [1237038243]
    def _n():
