    def r(lo, hi):
        return lo + ((_n() << 23) | _n()) % (hi - lo + 1)
    V = 6
    MODE = 1
    N = 200000
    if MODE == 1:
        a = list(range(1, N + 1))
    elif MODE == 2:
        a = [V] * N
    else:
        a = [r(0, V) for _ in range(N)]
    return f"{N}\n{'' ''.join(map(str, a))}\n"
', '10000100000', 0);
